import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt
AA3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H',
 'ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','MSE':'M'}
def fetch(pid):
    return requests.get(f"https://files.rcsb.org/download/{pid}.pdb",timeout=120).text
def parse(t,ch):
    o=[]
    for ln in t.split("\n"):
        if ln.startswith(("ATOM","HETATM")) and ln[16] in (" ","A"):
            rn=ln[17:20].strip()
            if rn not in AA3 or ln[21]!=ch: continue
            o.append((ln[12:16].strip(),AA3[rn],int(ln[22:26]),
                      np.array([float(ln[30:38]),float(ln[38:46]),float(ln[46:54])])))
    return o
def find_triad(at):
    ser={n:x for nm,r,n,x in at if r=='S' and nm=='OG'}
    his={}
    for nm,r,n,x in at:
        if r=='H' and nm in ('ND1','NE2'): his.setdefault(n,{})[nm]=x
    acid={}
    for nm,r,n,x in at:
        if r in 'DE' and nm in ('OD1','OD2','OE1','OE2'): acid.setdefault(n,[]).append(x)
    hits=[]
    for sn,sx in ser.items():
        for hn,hd in his.items():
            for a,b in (('NE2','ND1'),('ND1','NE2')):
                if a in hd and b in hd and np.linalg.norm(sx-hd[a])<3.4:
                    for an,axs in acid.items():
                        if min(np.linalg.norm(hd[b]-y) for y in axs)<3.4:
                            hits.append((sn,hn,an,float(np.linalg.norm(sx-hd[a])),
                                         float(min(np.linalg.norm(hd[b]-y) for y in axs))))
    return hits
CHG={'D':-1,'E':-1,'K':1,'R':1}
def pocket(at,sn,r):
    og=[x for nm,_,n,x in at if n==sn and nm=='OG'][0]
    res={}
    for nm,aa,n,x in at:
        if np.linalg.norm(x-og)<r: res[n]=aa
    return sum(CHG.get(v,0) for v in res.values()), len(res)

PANEL=[("4O8V","A","AlgJ P. putida","acetyl acceptor UNKNOWN"),
       ("4KNC","A","AlgX P. aeruginosa","alginate (polyanion)"),
       ("7ULA","B","AlgX P. putida (AlgKX)","alginate (polyanion)"),
       ("7TJB","A","PatB N. gonorrhoeae","peptidoglycan"),
       ("8TLB","A","PatB C. jejuni","peptidoglycan"),
       ("5UFY","A","OatA-C S. pneumoniae","peptidoglycan"),
       ("6VJP","A","OatA-C S. aureus","peptidoglycan")]
rows=[]
for pid,ch,lab,acc in PANEL:
    t=fetch(pid)
    at=parse(t,ch)
    if not at:
        chains=sorted({ln[21] for ln in t.split("\n") if ln.startswith("ATOM")})
        ch=chains[0]; at=parse(t,ch)
    hits=find_triad(at)
    if not hits:
        print(pid,lab,"-> no Ser-His-Asp/Glu triad auto-detected (chain %s)"%ch); continue
    # pick the triad whose Ser is most buried-but-accessible / take best geometry
    sn,hn,an,d1,d2=sorted(hits,key=lambda h:h[3])[0]
    row={"pdb":pid,"chain":ch,"protein":lab,"known_acceptor":acc,
         "triad":f"S{sn}-H{hn}-D/E{an}","SerOG_HisN":round(d1,2),"HisN_acid":round(d2,2),
         "n_res_chain":len({n for _,_,n,_ in at})}
    for r in (10,12,15):
        q,n=pocket(at,sn,r); row[f"q@{r}A"]=q; row[f"n@{r}A"]=n
    rows.append(row)
df=pd.DataFrame(rows)
pd.set_option("display.width",250); pd.set_option("display.max_columns",30)
print(df.to_string(index=False))

fig,ax=plt.subplots(figsize=(9,4.6))
order=df.sort_values("q@12A")
cols=['#C0504D' if 'AlgJ' in p else ('#4F81BD' if 'AlgX' in p else '#9BBB59') for p in order.protein]
ax.barh(range(len(order)),order["q@12A"],color=cols)
ax.set_yticks(range(len(order)))
ax.set_yticklabels([f"{r.protein}\n[{r.known_acceptor}]  {r.pdb}" for r in order.itertuples()],fontsize=7.5)
ax.axvline(0,color='grey',lw=0.8)
ax.set_xlabel('net formal charge of residues within 12 A of the catalytic Ser OG')
ax.set_title('SGNH acetyl-ester enzymes: active-site charge vs known acceptor\n'
             'AlgJ is the only one with a strongly acidic site; every enzyme with a polymer acceptor is neutral or basic',fontsize=9)
plt.tight_layout(); plt.show()
df.to_csv("/tmp/sgnh_panel.csv",index=False)
